/**
 * Check for a newer release
 *
 * Queries the GitHub releases API for the latest stable release and
 * compares it against the running build version. Returns
 * `available: false` when already up to date, running a dev build,
 * or when the API is unreachable (network failures are silenced).
 *
 */
export const checkForUpdate = <ThrowOnError extends boolean = false>(options?: Options<CheckForUpdateData, ThrowOnError>): RequestResult<CheckForUpdateResponses, unknown, ThrowOnError> => (options?.client ?? client).get<CheckForUpdateResponses, unknown, ThrowOnError>({ url: '/api/v1/system/update', ...options });

/**
 * Download + apply the latest game data (no binary update)
 *
 * Downloads `heroes.yaml`, `maps.yaml`, and
 * `screenshot_sources.yaml` from the Pages-published `main`
 * channel at https://sound-barrier.github.io/recall/data/,
 * verifies each against its published SHA-256 sidecar,
 * atomically writes them to `<RECALL_DATA_DIR>/data/`, and
 * swaps the parser dataset in-process. No binary update
 * required — the user can recognize newly-shipped heroes /
 * maps / capture-tool grammars by clicking Apply, without
 * re-installing Recall.
 *
 * Always pulls from `main` (the freshest data channel). Users
 * who want release-tagged YAML just upgrade the Recall binary,
 * which re-bundles the same files.
 *
 * Returns 422 if any asset's SHA-256 sidecar fails verification;
 * 500 on I/O failure; 502 if Pages is unreachable.
 *
 */
export const applyGameDataUpdate = <ThrowOnError extends boolean = false>(options?: Options<ApplyGameDataUpdateData, ThrowOnError>): RequestResult<ApplyGameDataUpdateResponses, ApplyGameDataUpdateErrors, ThrowOnError> => (options?.client ?? client).post<ApplyGameDataUpdateResponses, ApplyGameDataUpdateErrors, ThrowOnError>({ url: '/api/v1/system/data-update', ...options });

/**
 * Start an in-app binary self-update
 *
 * Kicks off a background check-then-download-and-install of the
 * newest release for this platform, streamed and SHA-256-verified
 * against the release's `SHA256SUMS`. The effect is out-of-band:
 * progress and the terminal outcome arrive as `wails:updater:*`
 * events the About dialog renders, so the response is `202` with
 * no body. Single-flighted server-side — a second call while one
 * is in flight is a silent no-op.
 *
 * `409` when self-update isn't possible on this install: server
 * mode (always), dev builds, non-Windows builds (Recall ships
 * Windows only; macOS is a dev-only target), or an install
 * directory the running user can't overwrite (a legacy
 * machine-wide Program Files install). The frontend reads
 * `can_self_update` on `GET /system/update` and won't call this
 * when it's false; the `409` is for scripted callers.
 *
 */
export const startSelfUpdate = <ThrowOnError extends boolean = false>(options?: Options<StartSelfUpdateData, ThrowOnError>): RequestResult<StartSelfUpdateResponses, StartSelfUpdateErrors, ThrowOnError> => (options?.client ?? client).post<StartSelfUpdateResponses, StartSelfUpdateErrors, ThrowOnError>({ url: '/api/v1/system/self-update', ...options });

/**
 * Apply a staged self-update and relaunch
 *
 * Swaps the staged binary in place and relaunches. Called after a
 * prior self-update reaches the ready state (the
 * `wails:updater:update-ready` event). On success the process
 * exits and the new binary starts, so the client normally never
 * receives a response; `202` is the "accepted, restarting" shape.
 * `409` when no updater is wired (same gates as
 * `POST /api/v1/system/self-update`).
 *
 */
export const restartToApply = <ThrowOnError extends boolean = false>(options?: Options<RestartToApplyData, ThrowOnError>): RequestResult<RestartToApplyResponses, RestartToApplyErrors, ThrowOnError> => (options?.client ?? client).post<RestartToApplyResponses, RestartToApplyErrors, ThrowOnError>({ url: '/api/v1/system/self-update/restart', ...options });

/**
 * Report the on-disk paths used by this install
 *
 * Surface the SQLite database path, settings file path, base
 * data directory, and the currently-configured screenshots
 * folder. Honors the `RECALL_DATA_DIR` env override (set in
 * mise.toml `[env]` for `wails dev`), so the response matches what
 * the running app actually reads/writes.
 *
 */
export const getDataLocation = <ThrowOnError extends boolean = false>(options?: Options<GetDataLocationData, ThrowOnError>): RequestResult<GetDataLocationResponses, unknown, ThrowOnError> => (options?.client ?? client).get<GetDataLocationResponses, unknown, ThrowOnError>({ url: '/api/v1/system/data-location', ...options });

/**
 * Overwatch reference data (hero roster + map roster)
 *
 * Returns the static reference data baked into the parser at
 * compile time from `pkg/parser/heroes.yaml` and
 * `pkg/parser/maps.yaml`. Stable across an app session — the
 * frontend may fetch once at load and cache. Source-of-truth
 * for UI surfaces that render canonical Blizzard spelling
 * (diacritics + capitalization preserved) and group heroes by
 * role / maps by game mode.
 *
 */
export const getReferenceData = <ThrowOnError extends boolean = false>(options?: Options<GetReferenceDataData, ThrowOnError>): RequestResult<GetReferenceDataResponses, unknown, ThrowOnError> => (options?.client ?? client).get<GetReferenceDataResponses, unknown, ThrowOnError>({ url: '/api/v1/system/reference-data', ...options });

/**
 * List the Windows screenshot-source picker candidates
 *
 * Returns the four canonical Windows capture-source locations
 * (Nvidia Overlay, OW PrntScn default, Win Snip tool, Steam
 * install) so the first-run Settings empty-state can render a
 * 2 × 2 picker grid. Each entry carries the resolved first
 * existing path variant for that source plus an `exists` flag
 * so the UI can render missing-path cards as grayed-with-
 * tooltip without a second round-trip.
 *
 * Returns an empty array on macOS / Linux — auto-detect is
 * Windows-only by current product decision; the frontend
 * hides the grid on those platforms and falls back to the
 * existing "Pick your screenshots folder…" button.
 *
 */
export const getScreenshotsFolderCandidates = <ThrowOnError extends boolean = false>(options?: Options<GetScreenshotsFolderCandidatesData, ThrowOnError>): RequestResult<GetScreenshotsFolderCandidatesResponses, unknown, ThrowOnError> => (options?.client ?? client).get<GetScreenshotsFolderCandidatesResponses, unknown, ThrowOnError>({ url: '/api/v1/system/screenshots-folder-candidates', ...options });

/**
 * Per-source diagnostic stats for the picker grid
 *
 * Walks the first-existing path of each candidate source and
 * returns the file count, last-write timestamp, and the count
 * of files whose names match the parser's recognized filename
 * grammars. Surfaced as a second metadata line on each picker
 * card — "47 files · 2h ago" / "0 files" / "12 files · 0
 * recognized" — so the user instantly knows which source their
 * captures are landing in.
 *
 * Decoupled from the picker's primary fetch because the dir
 * walk can spin for a few seconds on a synced cloud folder
 * with thousands of unrelated entries. The frontend issues
 * this AFTER the cards mount so the grid renders snappy and
 * the per-card stats line hydrates when the response lands.
 *
 * Walk is bounded to 1000 entries per source. Returns an empty
 * array on macOS / Linux (same Windows-only contract as the
 * plain candidates endpoint).
 *
 */
export const getScreenshotsFolderCandidateStats = <ThrowOnError extends boolean = false>(options?: Options<GetScreenshotsFolderCandidateStatsData, ThrowOnError>): RequestResult<GetScreenshotsFolderCandidateStatsResponses, unknown, ThrowOnError> => (options?.client ?? client).get<GetScreenshotsFolderCandidateStatsResponses, unknown, ThrowOnError>({ url: '/api/v1/system/screenshots-folder-candidates/stats', ...options });

/**
 * Probe the OS for an installed Tesseract binary
 *
 * Walks an ordered list of per-platform candidate paths
 * (Homebrew + MacPorts on macOS; apt / snap / Flatpak on Linux;
 * Program Files + Chocolatey + per-user AppData + scoop on
 * Windows) and returns the first one that resolves to a working
 * Tesseract 5.x binary. Falls back to `PATH` lookup if none of
 * the well-known locations match.
 *
 * Each candidate is validated via the same `--version` check as
 * `GET /api/v1/settings/tesseract` so a forgotten 3.x install
 * on `PATH` doesn't "succeed" while producing wrong OCR output.
 *
 * Read-only — does not persist. The caller (UI Detect button)
 * decides whether to apply the discovered path via
 * `PUT /api/v1/settings/tesseract`.
 *
 */
export const probeTesseractBinary = <ThrowOnError extends boolean = false>(options?: Options<ProbeTesseractBinaryData, ThrowOnError>): RequestResult<ProbeTesseractBinaryResponses, unknown, ThrowOnError> => (options?.client ?? client).get<ProbeTesseractBinaryResponses, unknown, ThrowOnError>({ url: '/api/v1/system/tesseract-probe', ...options });

/**
 * Open the configured screenshots folder in the host OS file manager
 *
 * Action endpoint — the effect (a Finder / Explorer / xdg-open
 * window appearing on the server's host) is out-of-band relative
 * to the HTTP response. The opener choice is per-platform:
 *
 * * macOS:   `open <path>`
 * * Linux:   `xdg-open <path>`
 * * Windows: `explorer <path>`
 *
 * The path is the in-memory `settings.ScreenshotsDir`, re-
 * validated via the same `validateScreenshotsDir` boundary used
 * by `PUT /api/v1/settings/screenshots-folder` before reaching
 * the shell. Replaces an earlier frontend behavior that called
 * `BrowserOpenURL('file://…')`, which Wails v2.12 rejects with
 * "scheme not allowed".
 *
 * No request body — the configured folder is the only thing
 * this action can reveal, so passing an arbitrary path would
 * widen the attack surface for no UX gain.
 *
 */
export const revealScreenshotsFolder = <ThrowOnError extends boolean = false>(options?: Options<RevealScreenshotsFolderData, ThrowOnError>): RequestResult<RevealScreenshotsFolderResponses, RevealScreenshotsFolderErrors, ThrowOnError> => (options?.client ?? client).post<RevealScreenshotsFolderResponses, RevealScreenshotsFolderErrors, ThrowOnError>({ url: '/api/v1/system/screenshots-folder-reveal', ...options });

/**
 * Download a complete native SQLite snapshot of the database
 *
 * Streams a consistent, compacted snapshot of the entire local
 * database (produced with `VACUUM INTO`). Unlike a per-table export
 * it captures every table verbatim — reviews, the ignored and
 * all-heroes lists, ambiguous candidates — so it is a true backup.
 * Restore it with `PUT /api/v1/database`.
 *
 */
export const backupDatabase = <ThrowOnError extends boolean = false>(options?: Options<BackupDatabaseData, ThrowOnError>): RequestResult<BackupDatabaseResponses, BackupDatabaseErrors, ThrowOnError> => (options?.client ?? client).get<BackupDatabaseResponses, BackupDatabaseErrors, ThrowOnError>({ url: '/api/v1/database', ...options });

/**
 * Restore the local database from a native SQLite snapshot
 *
 * REPLACES the entire local database with the uploaded `.db`
 * snapshot (as produced by `GET /api/v1/database`). The candidate is
 * validated read-only before any destructive step, so an invalid
 * upload leaves the running database untouched.
 *
 * Rejections: a file that is not a usable Recall database is `422`;
 * a parse in flight is `409`. Callers should surface a confirmation
 * step — this is a full replace.
 *
 */
export const restoreDatabase = <ThrowOnError extends boolean = false>(options: Options<RestoreDatabaseData, ThrowOnError>): RequestResult<RestoreDatabaseResponses, RestoreDatabaseErrors, ThrowOnError> => (options.client ?? client).put<RestoreDatabaseResponses, RestoreDatabaseErrors, ThrowOnError>({
    bodySerializer: null,
    url: '/api/v1/database',
    ...options,
    headers: {
        'Content-Type': 'application/octet-stream',
        ...options.headers
    }
});

/**
 * Report database integrity + size statistics
 *
 * Runs `PRAGMA integrity_check` plus the page/freelist pragmas
 * and stats the database + WAL files. Read-only — safe while a
 * parse is running. `integrity` is `ok` or the first problem
 * line SQLite reported; a non-ok value means the database needs
 * restoring from a backup.
 *
 */
export const getDatabaseHealth = <ThrowOnError extends boolean = false>(options?: Options<GetDatabaseHealthData, ThrowOnError>): RequestResult<GetDatabaseHealthResponses, GetDatabaseHealthErrors, ThrowOnError> => (options?.client ?? client).get<GetDatabaseHealthResponses, GetDatabaseHealthErrors, ThrowOnError>({ url: '/api/v1/database/health', ...options });

/**
 * Run a database maintenance operation
 *
 * Executes one maintenance operation and returns the refreshed
 * health report. `optimize` runs `PRAGMA optimize` (SQLite's
 * analyze-if-useful hook, cheap); `vacuum` rebuilds the file to
 * reclaim freelist pages and truncates the WAL (takes an
 * exclusive lock — serialized against parses, `409` while one
 * is in flight).
 *
 */
export const runDatabaseMaintenance = <ThrowOnError extends boolean = false>(options: Options<RunDatabaseMaintenanceData, ThrowOnError>): RequestResult<RunDatabaseMaintenanceResponses, RunDatabaseMaintenanceErrors, ThrowOnError> => (options.client ?? client).post<RunDatabaseMaintenanceResponses, RunDatabaseMaintenanceErrors, ThrowOnError>({
    url: '/api/v1/database/maintenance',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Build a selection-aware export bundle (ZIP)
 *
 * Builds a `.zip` containing a `recall-export/v2` JSON payload
 * (filtered to the requested matches) at `data.json`, every
 * referenced screenshot under `screenshots/<filename>`, and a
 * root `manifest.json` listing screenshot → match_key mappings
 * for sanity-checking after restore.
 *
 * The `match_keys` body field carries the user's explicit
 * selection. `include_unknown` adds every record whose
 * `data.map` is empty (the same "unknown" definition the
 * Matches view uses); `include_hidden` adds every record
 * currently in `hidden_matches`. Toggles UNION onto the
 * explicit selection — a request with `match_keys: []` and
 * `include_hidden: true` exports every hidden match.
 *
 * Merge into another install via `POST /api/v1/imports` — the
 * `data.json` shape is the `recall-export/v2` envelope, which
 * carries the user layer (edits, annotations, reviews, queue and
 * play-mode picks, hidden and pinned flags) alongside the OCR row
 * tables. `recall-export/v1` bundles still import unchanged.
 *
 * Supplying `share` switches the export to SHARE mode — the
 * bundle a player hands a coach. The manifest then carries a
 * `player` block (stable id + display handle + the player's
 * optional message), which is what `POST /api/v1/coach/session`
 * opens the session on. A share-mode bundle is deliberately NOT
 * importable: `POST /api/v1/imports` refuses it with `409` so a
 * mis-clicked Import cannot merge somebody else's history.
 *
 */
export const exportBundle = <ThrowOnError extends boolean = false>(options: Options<ExportBundleData, ThrowOnError>): RequestResult<ExportBundleResponses, ExportBundleErrors, ThrowOnError> => (options.client ?? client).post<ExportBundleResponses, ExportBundleErrors, ThrowOnError>({
    url: '/api/v1/exports/bundle',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Build a parser-triage diagnostic bundle (ZIP)
 *
 * Builds a `.zip` for bug reports when screenshots won't parse:
 * every ledgered failed screenshot still on disk under
 * `screenshots/<filename>`, the app logs (`logs/recall.log` plus
 * the rotated `.1` when present), and a root `manifest.json`
 * (`recall-diagnostic/v1`) carrying the app version, an
 * environment snapshot (OS/arch, Tesseract path + version), and
 * each failure's error, attempt count, and decoded image
 * resolution.
 *
 * Deliberately excludes `settings.json` and the database — the
 * bundle is for parser triage and stays safe to share. No request
 * body. An empty failure ledger is a 409: there is nothing to
 * diagnose.
 *
 */
export const exportDiagnosticBundle = <ThrowOnError extends boolean = false>(options?: Options<ExportDiagnosticBundleData, ThrowOnError>): RequestResult<ExportDiagnosticBundleResponses, ExportDiagnosticBundleErrors, ThrowOnError> => (options?.client ?? client).post<ExportDiagnosticBundleResponses, ExportDiagnosticBundleErrors, ThrowOnError>({ url: '/api/v1/exports/diagnostic', ...options });

/**
 * Import a bundle's matches or a coach's notes archive
 *
 * Accepts either archive a user can hand Recall and tells them apart
 * by ZIP entry names before any JSON is parsed, so a hostile payload
 * cannot pick its own reader. The response's `kind` says which one
 * arrived.
 *
 * A `recall-bundle/v1` ZIP (as produced by
 * `POST /api/v1/exports/bundle`) MERGES into the local database.
 * ADDITIVE — a match whose key already exists locally is skipped, and
 * nothing is ever wiped. Only the bundle's parsed rows (`data.json`)
 * are imported; the embedded screenshot images are ignored
 * (data-only).
 *
 * A `recall-coach-notes/v1` ZIP is STAGED as a return sheet and
 * changes no match: the player accepts or skips each note through
 * `PUT /api/v1/coach/returns/{id}/decisions`. Because staging writes
 * no match data, it is allowed on the read-only sample profile — a
 * bundle merge is not.
 *
 * Payload-level failures (not a ZIP, unreadable archive, missing
 * manifest/data.json or notes.json) are rejected with `400`;
 * semantic failures — an unsupported schema, a bundle a player
 * shared FOR coaching (open it as a session instead), a coaching
 * session in progress, a notes file with nothing to show (no
 * summary AND no note about a match in this history) — with `409`.
 * A notes file carrying only a session summary IS stageable.
 * Existing data is left untouched in both rejection paths.
 *
 * For a full-fidelity backup/restore (every table, including edits
 * and review state) use `GET` / `PUT /api/v1/database` instead.
 *
 */
export const importMatches = <ThrowOnError extends boolean = false>(options: Options<ImportMatchesData, ThrowOnError>): RequestResult<ImportMatchesResponses, ImportMatchesErrors, ThrowOnError> => (options.client ?? client).post<ImportMatchesResponses, ImportMatchesErrors, ThrowOnError>({
    bodySerializer: null,
    url: '/api/v1/imports',
    ...options,
    headers: {
        'Content-Type': 'application/zip',
        ...options.headers
    }
});

/**
 * End the coaching session
 *
 * Discards the loaned records. The coach's notes about the player
 * stay — they are keyed by player, not by session. Idempotent:
 * closing a session that is already gone returns 204.
 *
 */
export const closeCoachSession = <ThrowOnError extends boolean = false>(options?: Options<CloseCoachSessionData, ThrowOnError>): RequestResult<CloseCoachSessionResponses, CloseCoachSessionErrors, ThrowOnError> => (options?.client ?? client).delete<CloseCoachSessionResponses, CloseCoachSessionErrors, ThrowOnError>({ url: '/api/v1/coach/session', ...options });

/**
 * Read the open coaching session
 *
 * Returns the open session hydrated with everything the coach has
 * already written about this player. `404` when none is open — which
 * is how a reloaded tab learns its resume flag is stale.
 *
 */
export const getCoachSession = <ThrowOnError extends boolean = false>(options?: Options<GetCoachSessionData, ThrowOnError>): RequestResult<GetCoachSessionResponses, GetCoachSessionErrors, ThrowOnError> => (options?.client ?? client).get<GetCoachSessionResponses, GetCoachSessionErrors, ThrowOnError>({ url: '/api/v1/coach/session', ...options });

/**
 * Open a player's bundle as a coaching session
 *
 * Loans a player's exported bundle into memory for the length of a
 * review. The player's matches are rendered from the ZIP and never
 * written to this database, and they are discarded when the session
 * closes. Only the coach's OWN notes about the player persist — keyed
 * by player, so they resurface the next time that bundle is opened.
 *
 * One session at a time: a second open is a `409`. While a session is
 * open every mutating endpoint is refused with `409` — the coach is
 * looking at somebody else's history, so a write aimed at "this
 * match" would land on a key this database has never seen.
 *
 * A bundle that names its player (a "share with a coach" export —
 * `POST /api/v1/exports/bundle` with a `share` block) arrives with
 * the handle pre-filled; an anonymous one leaves it blank until
 * `PUT /api/v1/coach/session/player` confirms one. An identity no
 * export would have written (a non-UUID id, a blank or oversized
 * handle) is a `409`: it is refused rather than keyed on, because
 * the coach's own notes file would later refuse to carry it.
 *
 */
export const openCoachSession = <ThrowOnError extends boolean = false>(options: Options<OpenCoachSessionData, ThrowOnError>): RequestResult<OpenCoachSessionResponses, OpenCoachSessionErrors, ThrowOnError> => (options.client ?? client).post<OpenCoachSessionResponses, OpenCoachSessionErrors, ThrowOnError>({
    bodySerializer: null,
    url: '/api/v1/coach/session',
    ...options,
    headers: {
        'Content-Type': 'application/zip',
        ...options.headers
    }
});

/**
 * Confirm who the session is about
 *
 * The bundle suggests, the coach confirms. When the bundle minted a
 * stable player id the row is found by that id and renamed; when it
 * did not, the handle itself is the identity, so typing a different
 * one switches to that player. Either way the notes for the resolved
 * player re-hydrate, which is why the whole view is the response.
 *
 */
export const setCoachSessionPlayer = <ThrowOnError extends boolean = false>(options: Options<SetCoachSessionPlayerData, ThrowOnError>): RequestResult<SetCoachSessionPlayerResponses, SetCoachSessionPlayerErrors, ThrowOnError> => (options.client ?? client).put<SetCoachSessionPlayerResponses, SetCoachSessionPlayerErrors, ThrowOnError>({
    url: '/api/v1/coach/session/player',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * The loaned corpus
 *
 * The player's matches as the six tabs render them while a session is
 * open — the same `MatchRecord` shape as `GET /api/v1/matches`,
 * assembled from the bundle in memory with no store involved.
 *
 * Two deliberate departures: no ambiguity candidates travel in a
 * bundle, and `thumbnail_file` / `source_dir_ids` are blank so
 * nothing ever resolves a screenshot against the coach's disk.
 *
 */
export const getCoachSessionMatches = <ThrowOnError extends boolean = false>(options?: Options<GetCoachSessionMatchesData, ThrowOnError>): RequestResult<GetCoachSessionMatchesResponses, GetCoachSessionMatchesErrors, ThrowOnError> => (options?.client ?? client).get<GetCoachSessionMatchesResponses, GetCoachSessionMatchesErrors, ThrowOnError>({ url: '/api/v1/coach/session/matches', ...options });

/**
 * Remove the coach's note about one match
 *
 * What the autosave sends when a draft goes empty. Idempotent —
 * deleting a note that was never written returns 204.
 *
 */
export const deleteCoachNote = <ThrowOnError extends boolean = false>(options: Options<DeleteCoachNoteData, ThrowOnError>): RequestResult<DeleteCoachNoteResponses, DeleteCoachNoteErrors, ThrowOnError> => (options.client ?? client).delete<DeleteCoachNoteResponses, DeleteCoachNoteErrors, ThrowOnError>({ url: '/api/v1/coach/session/notes/{match_key}', ...options });

/**
 * Save the coach's note about one match
 *
 * Upserts the coach's one note about one of the session's matches —
 * the note editor's autosave target. The note replaces any earlier
 * one for the same match; its identity (`note_id`) is minted once and
 * survives every re-save and re-export, so the player's side can
 * dedupe and record decisions against it.
 *
 * `404` when no session is open or the match is not in the loaned
 * corpus, `409` before the player's handle has been confirmed.
 *
 */
export const putCoachNote = <ThrowOnError extends boolean = false>(options: Options<PutCoachNoteData, ThrowOnError>): RequestResult<PutCoachNoteResponses, PutCoachNoteErrors, ThrowOnError> => (options.client ?? client).put<PutCoachNoteResponses, PutCoachNoteErrors, ThrowOnError>({
    url: '/api/v1/coach/session/notes/{match_key}',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Remove one moment
 *
 * Idempotent. The note is deliberately left behind — a match whose
 * last moment was deleted is still a match the coach looked at.
 *
 */
export const deleteCoachMoment = <ThrowOnError extends boolean = false>(options: Options<DeleteCoachMomentData, ThrowOnError>): RequestResult<DeleteCoachMomentResponses, DeleteCoachMomentErrors, ThrowOnError> => (options.client ?? client).delete<DeleteCoachMomentResponses, DeleteCoachMomentErrors, ThrowOnError>({ url: '/api/v1/coach/session/notes/{match_key}/moments/{moment_id}', ...options });

/**
 * Save one timestamped moment on a match
 *
 * Upserts one observation inside the note for a match — "3:23, you did
 * not take the off-angle". Several moments share a match, which is the
 * whole point: the note itself carries a single optional clock, so a
 * coach with three things to say at three times could only stamp one.
 *
 * Creates the match's note if this is the first mark on it, as a
 * `reviewed_only` note — the coach HAS reviewed the match, they just
 * said it with a timestamp rather than a paragraph.
 *
 * `404` when no session is open or the match is not in the loaned
 * corpus. `400` when the clock is not `MM:SS` or the match already
 * holds the maximum of 50 moments. `409` before the player's handle
 * has been confirmed, and when the text is empty — the body parsed
 * fine, so the refusal is semantic rather than a malformed request.
 *
 */
export const putCoachMoment = <ThrowOnError extends boolean = false>(options: Options<PutCoachMomentData, ThrowOnError>): RequestResult<PutCoachMomentResponses, PutCoachMomentErrors, ThrowOnError> => (options.client ?? client).put<PutCoachMomentResponses, PutCoachMomentErrors, ThrowOnError>({
    url: '/api/v1/coach/session/notes/{match_key}/moments/{moment_id}',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Save the session summary
 *
 * The one set-level note for the session's player ("what to work
 * on"). An empty `text` clears it, so the field is required but may
 * be blank.
 *
 */
export const putCoachSummary = <ThrowOnError extends boolean = false>(options: Options<PutCoachSummaryData, ThrowOnError>): RequestResult<PutCoachSummaryResponses, PutCoachSummaryErrors, ThrowOnError> => (options.client ?? client).put<PutCoachSummaryResponses, PutCoachSummaryErrors, ThrowOnError>({
    url: '/api/v1/coach/session/summary',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Export the session's notes as an archive (ZIP)
 *
 * Packs the coach's work into the archive they hand the player:
 * `notes.json` (the machine copy the player's side ingests) and
 * `ledger.html` (the human copy nothing ever parses). `POST` because
 * it assembles a document rather than reading a resource.
 *
 * Refuses rather than shipping something unattributable: `404` with
 * no session open, `409` without a coach name in Settings, before the
 * player's handle is confirmed, or when there is no note and no
 * summary yet.
 *
 */
export const exportCoachNotes = <ThrowOnError extends boolean = false>(options?: Options<ExportCoachNotesData, ThrowOnError>): RequestResult<ExportCoachNotesResponses, ExportCoachNotesErrors, ThrowOnError> => (options?.client ?? client).post<ExportCoachNotesResponses, ExportCoachNotesErrors, ThrowOnError>({ url: '/api/v1/coach/session/export', ...options });

/**
 * The player's inbox of returned notes
 *
 * Every notes archive staged by `POST /api/v1/imports`, newest first,
 * with each note's derived status. "Pending" is derived, not stored:
 * a note with no decision whose match is still in this history. The
 * Matches banner counts exactly those.
 *
 */
export const listCoachReturns = <ThrowOnError extends boolean = false>(options?: Options<ListCoachReturnsData, ThrowOnError>): RequestResult<ListCoachReturnsResponses, ListCoachReturnsErrors, ThrowOnError> => (options?.client ?? client).get<ListCoachReturnsResponses, ListCoachReturnsErrors, ThrowOnError>({ url: '/api/v1/coach/returns', ...options });

/**
 * Discard a staged return sheet
 *
 * Drops the staged archive and its decisions. Blocks an earlier
 * accept already wrote onto matches STAY — they are the player's
 * notes now, and
 * `DELETE /api/v1/matches/{match_key}/coach-notes/{id}` removes those
 * one at a time.
 *
 */
export const deleteCoachReturn = <ThrowOnError extends boolean = false>(options: Options<DeleteCoachReturnData, ThrowOnError>): RequestResult<DeleteCoachReturnResponses, DeleteCoachReturnErrors, ThrowOnError> => (options.client ?? client).delete<DeleteCoachReturnResponses, DeleteCoachReturnErrors, ThrowOnError>({ url: '/api/v1/coach/returns/{id}', ...options });

/**
 * Read one staged return sheet
 *
 * One archive out of the inbox, with every note's status recomputed
 * against the current history — a note whose match was deleted since
 * it was staged reads back as an orphan.
 *
 */
export const getCoachReturn = <ThrowOnError extends boolean = false>(options: Options<GetCoachReturnData, ThrowOnError>): RequestResult<GetCoachReturnResponses, GetCoachReturnErrors, ThrowOnError> => (options.client ?? client).get<GetCoachReturnResponses, GetCoachReturnErrors, ThrowOnError>({ url: '/api/v1/coach/returns/{id}', ...options });

/**
 * Accept or skip notes on a return sheet
 *
 * Records the player's verdicts and returns the recomputed sheet. The
 * body is a PARTIAL map keyed by `note_id` — the player decides one
 * card at a time and a note the map omits stays pending, which is
 * what "Decide later" leaves behind.
 *
 * An accept writes the coach's block onto the match and marks it
 * reviewed by coach (overwriting a `self` review); a `reviewed_only`
 * mark sets only the flag. A skip removes a block an earlier accept
 * wrote. The batch is validated whole before anything is written, so
 * one bad entry writes nothing.
 *
 */
export const decideCoachReturn = <ThrowOnError extends boolean = false>(options: Options<DecideCoachReturnData, ThrowOnError>): RequestResult<DecideCoachReturnResponses, DecideCoachReturnErrors, ThrowOnError> => (options.client ?? client).put<DecideCoachReturnResponses, DecideCoachReturnErrors, ThrowOnError>({
    url: '/api/v1/coach/returns/{id}/decisions',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Remove an accepted coach note from a match
 *
 * The match journal's "Remove this note". The note must be ON that
 * match: a mismatched pair is a `404` rather than a delete of
 * somebody else's row.
 *
 */
export const deleteMatchCoachNote = <ThrowOnError extends boolean = false>(options: Options<DeleteMatchCoachNoteData, ThrowOnError>): RequestResult<DeleteMatchCoachNoteResponses, DeleteMatchCoachNoteErrors, ThrowOnError> => (options.client ?? client).delete<DeleteMatchCoachNoteResponses, DeleteMatchCoachNoteErrors, ThrowOnError>({ url: '/api/v1/matches/{match_key}/coach-notes/{id}', ...options });

/**
 * Read the coaching settings
 *
 * The name this user signs notes with as a coach. Empty means "not
 * set yet" — the Export affordance stays disabled until it is filled
 * in, because the ledger is rendered server-side and needs it.
 *
 */
export const getCoachingSettings = <ThrowOnError extends boolean = false>(options?: Options<GetCoachingSettingsData, ThrowOnError>): RequestResult<GetCoachingSettingsResponses, GetCoachingSettingsErrors, ThrowOnError> => (options?.client ?? client).get<GetCoachingSettingsResponses, GetCoachingSettingsErrors, ThrowOnError>({ url: '/api/v1/settings/coaching', ...options });

/**
 * Set the coach name
 *
 * Persists the name, trimmed. An empty string clears it — export then
 * refuses with `409` rather than shipping an unsigned archive.
 *
 */
export const setCoachingSettings = <ThrowOnError extends boolean = false>(options: Options<SetCoachingSettingsData, ThrowOnError>): RequestResult<SetCoachingSettingsResponses, SetCoachingSettingsErrors, ThrowOnError> => (options.client ?? client).put<SetCoachingSettingsResponses, SetCoachingSettingsErrors, ThrowOnError>({
    url: '/api/v1/settings/coaching',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Server-Sent Events stream
 *
 * Long-lived `text/event-stream` connection. Subscribers receive:
 * * `parse-progress` — fired per OCR'd file during a parse run;
 * payload is `ParseProgressEvent` (see `components.schemas`).
 * * `match-updated` — fired immediately after each successful
 * per-screenshot insert, carrying the fully-aggregated
 * `MatchRecord` for the affected `match_key`. Lets the
 * frontend incrementally render the Matches list as a parse
 * run progresses (upsert by `match_key`). Same shape as one
 * element of `GET /api/v1/matches`. May fire multiple
 * times for the same match within a single parse batch as
 * additional screenshots refine its fields.
 * * `parse-complete` — fired after a parse run finishes; no
 * payload.
 * * `parse-canceled` — fired when an in-flight run is aborted
 * via `DELETE /api/v1/parses/active`; no payload.
 * * `tesseract-status` — fired when the background engine probe
 * resolves; payload is `TesseractStatus`.
 * * `watch-activity` — fired when the folder watcher sees a new
 * screenshot and when a parse run starts; payload is
 * `WatchActivityEvent`. Drives the masthead's
 * "watching · N new" dot.
 * * `coach-session-changed` — fired when a coaching session opens
 * or closes; payload is `CoachSessionChangedEvent`. Every other
 * tab flips its write gate off `active` rather than re-fetching
 * the session.
 * * Keepalive comment lines every 25 s so reverse proxies
 * don't close the connection
 *
 * Clients should reconnect on disconnect; messages are not
 * replayed. After reconnect, the client should re-fetch
 * `GET /api/v1/matches` as the authoritative reconciliation.
 *
 * The desktop build delivers the same events over the Wails event
 * bus instead (the asset server cannot stream), so the payload
 * schemas here are the contract for BOTH transports.
 *
 */
export const events = <ThrowOnError extends boolean = false>(options?: Options<EventsData, ThrowOnError, EventsResponse>): Promise<ServerSentEventsResult<EventsResponses>> => (options?.client ?? client).sse.get<EventsResponses, unknown, ThrowOnError>({ url: '/api/v1/events', ...options });

/**
 * Serve a screenshot image from a recorded screenshots folder
 *
 * Streams a file from the screenshots directory identified by
 * `{dir_id}` — the `screenshots_dirs` row id recorded on the
 * screenshot's DB row, or `0` for "the currently configured
 * folder" (unparsed files in the watched dir). The `{filename}`
 * parameter must be a plain basename; path traversal (`..`, `/`,
 * `\`) is rejected. Used by the frontend to render `<img>`
 * previews without round-tripping bytes through the JSON bridge.
 * Sits outside `/api/v1/` because it serves binary content, not
 * JSON resources.
 *
 */
export const getScreenshot = <ThrowOnError extends boolean = false>(options: Options<GetScreenshotData, ThrowOnError>): RequestResult<GetScreenshotResponses, GetScreenshotErrors, ThrowOnError> => (options.client ?? client).get<GetScreenshotResponses, GetScreenshotErrors, ThrowOnError>({ url: '/_screenshot/{dir_id}/{filename}', ...options });
